public static class FrogRiver
{
    public static int Solution(int x, int[] a)
    {
        var hset = new HashSet<int>();
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] <= x) hset.Add(a[i]);
            if (hset.Count == x) return i;
