static int parse_number (const char *s, int i, int *num, int *m) {
    num[*m] = 0;
    while (isdigit ((unsigned char) s[i])) {
        num[*m] = num[*m] * 10 + s[i] - '0';
        ++i;
    }
    ++(*m);
    return i;
}

