def combinations(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r > n:
        return
    indices = list(range(r))
    while True:
        i = r - 1
        while i >= 0 and indices[i] == i + n - r:
            i -= 1
        if i < 0:
            return
        indices[i] += 1
        for j in range(i + 1, r):
            indices[j] = indices[j - 1] + 1
        current = tuple(pool[k] for k in indices)
        if 1 not in current or 3 not in current:
            yield current

internal static string GetIPAddress (HttpRequestBase request) {
    string forwarded = ExtractForwardedAddress(request);
    if (forwarded != null) {
        return forwarded;
    }
    string xForwardedFor = request.Headers ["X-Forwarded-For"];
    if (! String.IsNullOrEmpty (xForwardedFor)) {
        return xForwardedFor.Split (',') [0];
    }
    return request.UserHostAddress;
}

private static string ExtractForwardedAddress (HttpRequestBase request) {
    string forwarded = request.Headers ["Forwarded"];
    if (String.IsNullOrEmpty (forwarded)) {
        return null;
    }
    foreach (string segment in forwarded.Split (',') [0].Split (';')) {
        string [] pair = segment.Trim ().Split ('=');
        if (pair.Length != 2 || ! pair [0].Equals ("for", StringComparison.OrdinalIgnoreCase)) {
            continue;
        }
        return StripPortOrBrackets(pair [1].Trim ('"'));
    }
    return null;
}

private static string StripPortOrBrackets (string ip) {
    int left = ip.IndexOf ('[');
    if (left == 0) {
        int right = ip.IndexOf (']');
        return ip.Substring (1, right - 1);
    }
    int colon = ip.IndexOf (':');
    if (colon != - 1) {
        return ip.Substring (0, colon);
    }
    return ip;
}
